/**
 * Patch-composition failures (load-time; composition itself only warns).
 */
sealed class FfiComposeException: kotlin.Exception() {
    
    /**
     * A YAML layer could not be parsed.
     */
    class InvalidYaml(
        
        /**
         * Layer label.
         */
        val `label`: kotlin.String, 
        
        /**
         * Parser message.
         */
        val `reason`: kotlin.String
        ) : FfiComposeException() {
        override val message
            get() = "label=${ `label` }, reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FfiComposeException> {
        override fun lift(error_buf: RustBuffer.ByValue): FfiComposeException = FfiConverterTypeFfiComposeError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiComposeError : FfiConverterRustBuffer<FfiComposeException> {
    override fun read(buf: ByteBuffer): FfiComposeException {
        

        return when(buf.getInt()) {
            1 -> FfiComposeException.InvalidYaml(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiComposeException): ULong {
        return when(value) {
            is FfiComposeException.InvalidYaml -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`label`)
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: FfiComposeException, buf: ByteBuffer) {
        when(value) {
            is FfiComposeException.InvalidYaml -> {
                buf.putInt(1)
                FfiConverterString.write(value.`label`, buf)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}





/**
 * Session-log failures crossing the boundary.
 */
sealed class FfiLogException: kotlin.Exception() {
    
    /**
     * The file's header version is not supported by this build.
     */
    class UnsupportedFormatVersion(
        
        /**
         * Version found in the file header.
         */
        val `found`: kotlin.ULong, 
        
        /**
         * Version supported by this build.
         */
        val `supported`: kotlin.UInt
        ) : FfiLogException() {
        override val message
            get() = "found=${ `found` }, supported=${ `supported` }"
    }
    
    /**
     * A loaded record's seq does not continue the sequence.
     */
    class SeqDiscontinuity(
        
        /**
         * Index of the offending record.
         */
        val `index`: kotlin.ULong, 
        
        /**
         * Expected seq.
         */
        val `expected`: kotlin.ULong, 
        
        /**
         * Seq found.
         */
        val `found`: kotlin.ULong
        ) : FfiLogException() {
        override val message
            get() = "index=${ `index` }, expected=${ `expected` }, found=${ `found` }"
    }
    
    /**
     * A line of the file is not a well-formed log record.
     */
    class MalformedRecord(
        
        /**
         * One-based line number.
         */
        val `line`: kotlin.ULong, 
        
        /**
         * Why the record is malformed.
         */
        val `reason`: kotlin.String
        ) : FfiLogException() {
        override val message
            get() = "line=${ `line` }, reason=${ `reason` }"
    }
    
    /**
     * The file does not start with a header record.
     */
    class MissingHeader(
        ) : FfiLogException() {
        override val message
            get() = ""
    }
    
    /**
     * Persistence backend failure.
     */
    class Store(
        
        val v1: kotlin.String
        ) : FfiLogException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    /**
     * An appended payload was not valid JSON.
     */
    class InvalidPayloadJson(
        
        val v1: kotlin.String
        ) : FfiLogException() {
        override val message
            get() = "v1=${ v1 }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FfiLogException> {
        override fun lift(error_buf: RustBuffer.ByValue): FfiLogException = FfiConverterTypeFfiLogError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiLogError : FfiConverterRustBuffer<FfiLogException> {
    override fun read(buf: ByteBuffer): FfiLogException {
        

        return when(buf.getInt()) {
            1 -> FfiLogException.UnsupportedFormatVersion(
                FfiConverterULong.read(buf),
                FfiConverterUInt.read(buf),
                )
            2 -> FfiLogException.SeqDiscontinuity(
                FfiConverterULong.read(buf),
                FfiConverterULong.read(buf),
                FfiConverterULong.read(buf),
                )
            3 -> FfiLogException.MalformedRecord(
                FfiConverterULong.read(buf),
                FfiConverterString.read(buf),
                )
            4 -> FfiLogException.MissingHeader()
            5 -> FfiLogException.Store(
                FfiConverterString.read(buf),
                )
            6 -> FfiLogException.InvalidPayloadJson(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiLogException): ULong {
        return when(value) {
            is FfiLogException.UnsupportedFormatVersion -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterULong.allocationSize(value.`found`)
                + FfiConverterUInt.allocationSize(value.`supported`)
            )
            is FfiLogException.SeqDiscontinuity -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterULong.allocationSize(value.`index`)
                + FfiConverterULong.allocationSize(value.`expected`)
                + FfiConverterULong.allocationSize(value.`found`)
            )
            is FfiLogException.MalformedRecord -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterULong.allocationSize(value.`line`)
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is FfiLogException.MissingHeader -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FfiLogException.Store -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is FfiLogException.InvalidPayloadJson -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: FfiLogException, buf: ByteBuffer) {
        when(value) {
            is FfiLogException.UnsupportedFormatVersion -> {
                buf.putInt(1)
                FfiConverterULong.write(value.`found`, buf)
                FfiConverterUInt.write(value.`supported`, buf)
                Unit
            }
            is FfiLogException.SeqDiscontinuity -> {
                buf.putInt(2)
                FfiConverterULong.write(value.`index`, buf)
                FfiConverterULong.write(value.`expected`, buf)
                FfiConverterULong.write(value.`found`, buf)
                Unit
            }
            is FfiLogException.MalformedRecord -> {
                buf.putInt(3)
                FfiConverterULong.write(value.`line`, buf)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is FfiLogException.MissingHeader -> {
                buf.putInt(4)
                Unit
            }
            is FfiLogException.Store -> {
                buf.putInt(5)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is FfiLogException.InvalidPayloadJson -> {
                buf.putInt(6)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}





